CREATE TABLE catalog_recipe_metadata(recipe_id TEXT NOT NULL,recipe_version TEXT NOT NULL,model_type TEXT NOT NULL,style_id TEXT,PRIMARY KEY(recipe_id,recipe_version));
INSERT INTO catalog_recipe_metadata(recipe_id,recipe_version,model_type,style_id) VALUES ('work-lantern','0.6.0','Props','faceted-low-poly'), ('cottage','0.6.0','Buildings','faceted-low-poly'), ('tree','0.6.0','Nature','faceted-low-poly'), ('fence','0.6.0','Structures','faceted-low-poly'), ('crate','0.6.0','Props','faceted-low-poly'), ('boulder','0.6.0','Nature','faceted-low-poly'), ('bench','1.1.0','Props','faceted-low-poly'), ('planter','1.1.0','Props','faceted-low-poly'), ('treasure-chest','1.1.0','Props','faceted-low-poly'), ('wheelbarrow','1.1.0','Props','faceted-low-poly'), ('stone-well','1.1.0','Props','faceted-low-poly'), ('conifer','1.1.0','Nature','faceted-low-poly');
CREATE TRIGGER immutable_catalog_recipe_update BEFORE UPDATE ON catalog_recipe_metadata BEGIN SELECT RAISE(ABORT,'immutable_catalog_recipe_metadata'); END;
CREATE TRIGGER immutable_catalog_recipe_delete BEFORE DELETE ON catalog_recipe_metadata BEGIN SELECT RAISE(ABORT,'immutable_catalog_recipe_metadata'); END;
CREATE VIEW catalog_version_metadata AS SELECT v.*,m.model_type,m.style_id,CASE WHEN m.recipe_id IS NULL THEN 'unclassified' ELSE 'registered-recipe' END AS metadata_source FROM asset_version v LEFT JOIN catalog_recipe_metadata m ON json_extract(v.subject,'$.recipe.id')=m.recipe_id AND json_extract(v.subject,'$.recipe.version')=m.recipe_version AND json_extract(v.subject,'$.selectedDesign.family')=m.recipe_id AND json_extract(v.subject,'$.selectedDesign.familyVersion')=m.recipe_version;
CREATE VIEW catalog_discovery AS SELECT v.* FROM catalog_version_metadata v WHERE v.state='published' AND NOT EXISTS(SELECT 1 FROM asset_version newer WHERE newer.asset_id=v.asset_id AND newer.state='published' AND (COALESCE(newer.published_at,0)>COALESCE(v.published_at,0) OR (COALESCE(newer.published_at,0)=COALESCE(v.published_at,0) AND newer.id>v.id)));
